#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

    /// Specification: every element has the same parity as its index.
    spec fn all_odd_at_odd_positions(arr: &Vec<usize>) -> bool {
        forall |j: usize|  j < arr.len() ==> arr[j] % 2 == j % 2
    }

    /// Returns true iff `all_odd_at_odd_positions(arr)` holds.
    pub fn is_odd_at_odd_index(arr: &Vec<usize>) -> bool
        ensures result == all_odd_at_odd_positions(arr)
    {
        let mut i: usize = 0;
        let mut ok: bool  = true;
        // Loop until i == arr.len()
        while i < arr.len() {
            invariant i <= arr.len();
            // `ok` exactly records that all positions < i satisfy the parity law
            invariant ok == (forall |j: usize| j < i ==> arr[j] % 2 == j % 2);
            decreases arr.len() - i;

            let curr_match: bool = arr[i] % 2 == i % 2;
            ok = ok && curr_match;
            i += 1;
        }
        ok
    }

    // A short proof‐time test
    proof fn test_trivial() {
        let v0: Vec<usize> = Vec::empty();
        assert(is_odd_at_odd_index(&v0)); // empty ⇒ vacuously true

        let v1 = vec![0, 3, 4, 7,  6];
        //      ↑ ev, od, ev, od,  ev   ← all match
        assert(is_odd_at_odd_index(&v1));

        let v2 = vec![0, 2, 4, 6];
        //      ↑ ev, ev … FAILS at index=1
        assert(!is_odd_at_odd_index(&v2));
    }
}